export default function UnitServiceVideoCallsTableView({ patient }) {
  const table = useTable({ defaultOrderBy: 'code' });
  const { t } = useTranslate();
  const { currentLang } = useLocales();
  const curLangAr = currentLang.value === 'ar';
  const [search, setSearch] = useState('');
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const TABLE_HEAD = [
    { id: 'code', label: t('code') },
    { id: 'employee', label: t('employee') },
    { id: 'patient_name', label: t('patient') },
    { id: 'work_group', label: t('work group') },
    { id: 'duration', label: t('duration') },
    { id: 'description', label: t('description') },
    { id: 'actions', label: '', align: 'right' },
  ];
  
  const { data, isLoading } = useGetVideoCalls({ 
    patient_id: patient?._id,
    unit_service: patient?.unit_service,
  });
  const videoCalls = data?.videoCalls || data || [];
  const videoCallsWithNames = videoCalls.map((row) => ({
    ...row,
    patient_name: row.patient?.name_english || '',
  }));

  
  const filteredData = useMemo(() => {
    if (!search) return videoCallsWithNames;
    const lower = search.toLowerCase();
    return videoCallsWithNames.filter(
      (row) =>
        (row.code && row.code.toString().toLowerCase().includes(lower)) ||
        (row.employee?.name_english && row.employee.name_english.toLowerCase().includes(lower)) ||
        (row.patient_name && row.patient_name.toLowerCase().includes(lower)) ||
        (row.work_group?.name_english && row.work_group.name_english.toLowerCase().includes(lower)) ||
        (row.descriptionAR && row.descriptionAR.toLowerCase().includes(lower))
        (row.descriptionEN && row.descriptionEN.toLowerCase().includes(lower))
    );
  }, [search, videoCallsWithNames]);

  const dataFiltered = applyFilter({
    inputData: filteredData,
    comparator: getCustomComparator(table.order, table.orderBy),
  });

  const notFound = (!dataFiltered.length && !!videoCallsWithNames.length) || (!isLoading && !videoCallsWithNames.length);

  if (isLoading) {
    return <LoadingScreen />;
  }

  
  // eslint-disable-next-line react/no-unstable-nested-components
  function DesktopTableView() {
    return (
      <TableContainer sx={{ position: 'relative', overflow: 'unset' }}>
        <Scrollbar>
          <Table size={table.dense ? 'small' : 'medium'}>
            <TableHeadCustom
              order={table.order}
              orderBy={table.orderBy}
              headLabel={TABLE_HEAD}
              rowCount={dataFiltered.length}
              numSelected={table.selected.length}
              onSort={table.onSort}
            />
            <TableBody>
              {dataFiltered
                .slice(
                  table.page * table.rowsPerPage,
                  table.page * table.rowsPerPage + table.rowsPerPage
                )
                .map((row, idx) => (
                  <VideoCallTableRow
                    key={row.code || idx}
                    row={row}
                    idx={idx}
                    curLangAr={curLangAr}
                    t={t}
                  />
                ))}

              <TableNoData notFound={notFound} />
            </TableBody>
          </Table>
        </Scrollbar>
      </TableContainer>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ px: { xs: 1, sm: 2 } }}>
      <Card sx={{ 
        boxShadow: { xs: 0, sm: 1 },
        border: { xs: '1px solid', sm: 'none' },
        borderColor: 'divider'
      }}>
        <Stack 
          spacing={2} 
          alignItems={{ xs: 'stretch', md: 'center' }} 
          direction={{ xs: 'column', md: 'row' }} 
          sx={{ 
            p: { xs: 1.5, sm: 2.5 }, 
            pr: { xs: 1.5, sm: 2.5, md: 1 } 
          }}
        >
          <Stack 
            direction="row" 
            alignItems="center" 
            spacing={1} 
            sx={{ width: { xs: '100%', md: 'auto' } }}
          >
            <TextField
              fullWidth
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder={t('Search by code, patient, employee, or description...')}
              size={isMobile ? 'small' : 'medium'}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Iconify icon="eva:search-fill" sx={{ color: 'text.disabled', fontSize: isMobile ? 18 : 20 }} />
                  </InputAdornment>
                ),
              }}
              sx={{ 
                maxWidth: { md: 300, lg: 400 },
                '& .MuiInputBase-root': {
                  height: isMobile ? 40 : 48
                }
              }}
            />
          </Stack>
        </Stack>


        {isMobile ? (
          <Box sx={{ p: { xs: 1, sm: 2 } }}>
            {dataFiltered.length > 0 ? (
              dataFiltered
                .slice(
                  table.page * table.rowsPerPage,
                  table.page * table.rowsPerPage + table.rowsPerPage
                )
                .map((row, idx) => (
                  <MobileCardView 
                    key={row.code || idx} 
                    row={row} 
                    curLangAr={curLangAr}
                    t={t}
                  />
                ))
            ) : (
              <TableNoData notFound={notFound} />
            )}
          </Box>
        ) : (
          <DesktopTableView />
        )}

        <TablePaginationCustom
          count={dataFiltered.length}
          page={table.page}
          rowsPerPage={table.rowsPerPage}
          onPageChange={table.onChangePage}
          onRowsPerPageChange={table.onChangeRowsPerPage}
          dense={table.dense}
          onChangeDense={table.onChangeDense}
          sx={{
            '& .MuiTablePagination-select': {
              fontSize: { xs: 12, sm: 14 }
            },
            '& .MuiTablePagination-displayedRows': {
              fontSize: { xs: 12, sm: 14 }
            },
            '& .MuiTablePagination-actions': {
              '& .MuiIconButton-root': {
                fontSize: { xs: 18, sm: 22 }
              }
            }
          }}
        />
      </Card>
    </Container>
  );
}



function getCustomComparator(order, orderBy) {
  return (a, b) => {
    let aValue;
    let bValue;

    switch (orderBy) {
      case 'code':
        aValue = a.code || 0;
        bValue = b.code || 0;
        break;
      case 'employee':
        aValue = a.employee?.name_english || '';
        bValue = b.employee?.name_english || '';
        break;
      case 'patient_name':
        aValue = a.patient?.name_english || '';
        bValue = b.patient?.name_english || '';
        break;
      case 'work_group':
        aValue = a.work_group?.name_english || '';
        bValue = b.work_group?.name_english || '';
        break;
      case 'duration':
        aValue = a.duration || 0;
        bValue = b.duration || 0;
        break;
      case 'descriptionEN':
        aValue = a.descriptionEN || '';
        bValue = b.descriptionEN || '';
        break;
      case 'descriptionAR':
        aValue = a.descriptionAR || '';
        bValue = b.descriptionAR || '';
        break;
      default:
        aValue = a[orderBy] || '';
        bValue = b[orderBy] || '';
    }

    
    if (orderBy === 'code' || orderBy === 'duration') {
      if (order === 'desc') {
        return bValue - aValue;
      }
      return aValue - bValue;
    }

    
    if (order === 'desc') {
      return bValue.toString().localeCompare(aValue.toString());
    }
    return aValue.toString().localeCompare(bValue.toString());
  };
}

function applyFilter({ inputData, comparator }) {
  const stabilizedThis = inputData.map((el, index) => [el, index]);

  stabilizedThis.sort((a, b) => {
    const order = comparator(a[0], b[0]);
    if (order !== 0) return order;
    return a[1] - b[1];
  });

  inputData = stabilizedThis.map((el) => el[0]);

  return inputData;
}

